package app.departures.core

/** A line's official badge colours, as ARGB ints. */
data class LineColor(val background: Int, val text: Int)

/**
 * Official line colours, from `line_colors.csv` (generated by tools/line_colors.py from
 * OpenStreetMap and Traewelling/line-colors). Lines not listed get the app's default badge.
 */
object LineColors {
    private val table: Map<String, LineColor> by lazy {
        LineColors::class.java.getResourceAsStream("/line_colors.csv")
            ?.bufferedReader(Charsets.UTF_8)?.use { parse(it.readText()) }
            .orEmpty()
    }

    /** Colour for [line] run by [operator] (as the timetable API reports it), if known. */
    fun of(operator: String?, line: String): LineColor? {
        val op = operatorKey(operator) ?: return null
        return table[key(op, line)]
    }

    /**
     * The API's operator field is an abbreviation, sometimes with a suffix after spaces
     * ("VBZ    F", "SVB Auto"); only the first word identifies the operator.
     */
    internal fun operatorKey(operator: String?): String? =
        operator?.trim()?.split(Regex("\\s+"))?.firstOrNull()?.uppercase()?.takeIf { it.isNotEmpty() }

    private fun key(operator: String, line: String) = operator + "|" + line.trim().uppercase()

    internal fun parse(csv: String): Map<String, LineColor> = buildMap {
        for (raw in csv.lineSequence()) {
            val line = raw.trim()
            if (line.isEmpty() || line.startsWith("#") || line.startsWith("operator,")) continue
            val parts = line.split(',')
            if (parts.size < 4) continue
            val bg = parseHex(parts[2]) ?: continue
            val fg = parseHex(parts[3]) ?: continue
            put(key(parts[0].trim().uppercase(), parts[1]), LineColor(bg, fg))
        }
    }

    internal fun parseHex(hex: String): Int? {
        val h = hex.trim().removePrefix("#")
        if (h.length != 6) return null
        return h.toLongOrNull(16)?.let { (0xFF000000L or it).toInt() }
    }
}
